    end
  end

  def install
    # A bare download isn't executable yet, and codesynapse runs below to
    # generate its completions.
    binary = Dir["codesynapse-*"].first
    chmod 0755, binary
    bin.install binary => "codesynapse"
    generate_completions_from_executable(bin/"codesynapse", "completion")
  end

  def caveats
    <<~EOS
      Connect Claude Code with a personal key (Settings → API keys in the dashboard):
        CODESYNAPSE_MCP_TOKEN=csk_... codesynapse mcp install --only claude
      then open a new chat. The bridge follows `brew upgrade codesynapse`.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/codesynapse --version")
    assert_match "__start_codesynapse", (bash_completion/"codesynapse").read
    # The bridge refuses to start without a chat ID instead of inventing one.
    assert_match "no chat session", shell_output("#{bin}/codesynapse mcp bridge 2>&1", 1)
  end
end
